import re

def slugify(title: str) -> str:
    """'Hello, World!' -> 'hello-world'. Lowercase; runs of non-alphanumerics become one dash; no leading or
    trailing dash."""
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")

