from text_utils import slugify


def test_basic():
    assert slugify("Hello, World!") == "hello-world"


def test_collapses_runs_and_trims():
    assert slugify("  --A  B--  ") == "a-b"


def test_digits_kept():
    assert slugify("Top 10 Tips") == "top-10-tips"


def test_empty_and_symbols_only():
    assert slugify("") == ""
    assert slugify("!!!") == ""

import pytest

from durations import parse_duration


@pytest.mark.parametrize("text, want", [
    ("1h30m", 5400), ("45s", 45), ("2m5s", 125), (" 1h ", 3600)])
def test_valid(text, want):
    assert parse_duration(text) == want


@pytest.mark.parametrize("text", ["", "abc", "30m1h", "1.5h"])
def test_invalid(text):
    with pytest.raises(ValueError):
        parse_duration(text)
